367 | 		if err != nil && !IsErrMilestoneNotExist(err) {
368 | 			return fmt.Errorf("getMilestoneByID: %w", err)
369 | 		}
370 | 
371 | 		// Assume milestone is invalid and drop silently.
372 | 		opts.Issue.MilestoneID = 0
373 | 		if milestone != nil {
374 | 			opts.Issue.MilestoneID = milestone.ID
375 | 			opts.Issue.Milestone = milestone
376 | 		}
377 | 	}
378 | 
379 | 	if opts.Issue.Index <= 0 {
380 | 		return errors.New("no issue index provided")
381 | 	}
382 | 	if opts.Issue.ID > 0 {
383 | 		return errors.New("issue exist")
384 | 	}
385 | 
386 | 	if _, err := e.Insert(opts.Issue); err != nil {
387 | 		return err
388 | 	}
389 | 
390 | 	if opts.Issue.MilestoneID > 0 {
391 | 		if err := UpdateMilestoneCounters(ctx, opts.Issue.MilestoneID); err != nil {
