394 | 
395 | 		opts := &CreateCommentOptions{
396 | 			Type:           CommentTypeMilestone,
397 | 			Doer:           doer,
398 | 			Repo:           opts.Repo,
399 | 			Issue:          opts.Issue,
400 | 			OldMilestoneID: 0,
401 | 			MilestoneID:    opts.Issue.MilestoneID,
402 | 		}
403 | 		if _, err = CreateComment(ctx, opts); err != nil {
404 | 			return err
405 | 		}
406 | 	}
