408 | 	// Update repository issue total count
409 | 	if err := IncrRepoIssueNumbers(ctx, opts.Repo.ID, opts.Issue.IsPull, true); err != nil {
410 | 		return err
411 | 	}
412 | 
413 | 	if len(opts.LabelIDs) > 0 {
414 | 		// During the session, SQLite3 driver cannot handle retrieve objects after update something.
415 | 		// So we have to get all needed labels first.
416 | 		labels := make([]*Label, 0, len(opts.LabelIDs))
417 | 		if err = e.In("id", opts.LabelIDs).Find(&labels); err != nil {
418 | 			return fmt.Errorf("find all labels [label_ids: %v]: %w", opts.LabelIDs, err)
419 | 		}
420 | 
421 | 		if err = opts.Issue.LoadPoster(ctx); err != nil {
422 | 			return err
423 | 		}
424 | 
425 | 		for _, label := range labels {
426 | 			// Silently drop invalid labels.
427 | 			if label.RepoID != opts.Repo.ID && label.OrgID != opts.Repo.OwnerID {
428 | 				continue
429 | 			}
430 | 
431 | 			if err = newIssueLabel(ctx, opts.Issue, label, opts.Issue.Poster); err != nil {
432 | 				return fmt.Errorf("addLabel [id: %d]: %w", label.ID, err)
433 | 			}
434 | 		}
435 | 	}
436 | 
437 | 	if err = NewIssueUsers(ctx, opts.Repo, opts.Issue); err != nil {
438 | 		return err
439 | 	}
440 | 
441 | 	if err := UpdateIssueAttachments(ctx, opts.Issue.ID, opts.Attachments); err != nil {
442 | 		return err
443 | 	}
444 | 
445 | 	if err = opts.Issue.LoadAttributes(ctx); err != nil {
